cat > /private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/9cdd416f-bfa8-4210-acf3-8179611c79a2/scratchpad/probeMaxQty.mjs <<'EOF'
// READ-ONLY probe: does the live SFCC sandbox expose any max-order-quantity
// field or custom attribute on products? Mirrors switchEnv.mjs's liveCheckSfcc
// private-client client_credentials guest-token flow.
import {readFileSync} from 'node:fs';

const parseEnv = (p) => {
  const m = new Map();
  try {
    for (const line of readFileSync(p, 'utf8').split('\n')) {
      const t = line.trim();
      if (!t || t.startsWith('#')) continue;
      const i = t.indexOf('=');
      if (i === -1) continue;
      m.set(t.slice(0, i).trim(), t.slice(i + 1).trim().replace(/^["']|["']$/g, ''));
    }
  } catch { /* file may not exist */ }
  return m;
};

const env = new Map([...parseEnv('.env.shared'), ...parseEnv('.env.dev')]);
const shortCode = env.get('COMMERCE_API_SHORT_CODE');
const orgId = env.get('COMMERCE_API_ORGANIZATION_ID');
const clientId = env.get('COMMERCE_API_CLIENT_ID');
const secret = env.get('PWA_KIT_SLAS_CLIENT_SECRET');
const siteId = env.get('COMMERCE_API_SITE_ID');

if (!shortCode || !orgId || !clientId || !secret || !siteId) {
  console.log('SKIP — missing one of shortCode/orgId/clientId/secret/siteId in .env.shared+.env.dev');
  process.exit(0);
}

const base = `https://${shortCode}.api.commercecloud.salesforce.com`;
const tokenRes = await fetch(`${base}/shopper/auth/v1/organizations/${orgId}/oauth2/token`, {
  method: 'POST',
  headers: {
    Authorization: `Basic ${Buffer.from(`${clientId}:${secret}`).toString('base64')}`,
    'Content-Type': 'application/x-www-form-urlencoded',
  },
  body: new URLSearchParams({grant_type: 'client_credentials', channel_id: siteId}).toString(),
});
if (!tokenRes.ok) {
